"use client";
import { useEffect, useState } from "react";
import { getCookie } from "cookies-next";
import Breadcrumb from "@/components/header/breadcrumb";
import Menu from "./menu";
import getCreditDetailsList from "@/services/auth/profile/creditDetailsService";
import priceFormat from "@/helpers/priceFormat";
import CreditPieChart from "@/components/profile-page/creditPieChart";
import { parsePlainDate } from "@/helpers/plainDate";

const pillBase =
  "tw-inline-block tw-rounded-full tw-px-2.5 tw-py-1 tw-text-[11px] tw-font-semibold tw-capitalize";

export default function Page() {
  const [data, setData] = useState({
    available: 0,
    currency: "",
    pending: 0,
    transactions: [],
  });
  const [dataLoading, setDataLoading] = useState(true);
  const [totalBookingAmount, setTotalBookingAmount] = useState<number>(0.0);
  const [totalPaidAmount, setTotalPaidAmount] = useState(0);
  const [totalBalance, setTotalBalance] = useState(0);
  const [totalEarnedCredit, setTotalEarnedCredit] = useState(0);

  const loadCredits = async () => {
    scroll(0, 0);
    setDataLoading(true);
    // Sanctum (apiv3) token — kredi okuma artık apiv3 /b2c/credits.
    await getCreditDetailsList({
       token: (await getCookie("auth-token-v3"))!,
    }).then((res) => {
      setData(res);
      setDataLoading(false);
    });
  };

  useEffect(() => {
    loadCredits();
  }, []);

  useEffect(() => {
    if (data) {
      for (const item of data.transactions) {
        // @ts-ignore
        if (item.ticket_id) {
          // @ts-ignore
          const booking_amount = item.booking_amount ? parseFloat(item.booking_amount) : 0;
          setTotalBookingAmount((prevState) => prevState + booking_amount);

          // @ts-ignore
          const paid_amount = item.paid_amount ? parseFloat(item.paid_amount) : 0;
          setTotalPaidAmount((prevState) => prevState + paid_amount);

          // @ts-ignore
          const balance = item.balance ? parseFloat(item.balance) : 0;
          setTotalBalance((prevState) => prevState + balance);
        }
        // @ts-ignore
        if (item.type == "deposit") {
          // @ts-ignore
          const earned_credit = item.amount ? parseFloat(item.amount) : 0;
          setTotalEarnedCredit((prevState) => prevState + earned_credit);
        }
      }
    }
  }, [data]);

  const summary = [
    { label: "Total Bookings Amount", value: totalBookingAmount },
    { label: "Total Paid Amount", value: totalPaidAmount },
    { label: "Total Balance", value: totalBalance },
    { label: "Total Earned Credit", value: totalEarnedCredit },
  ];

  return (
    <main className="tw-font-display">
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">
        <Breadcrumb items={[{ pageTitle: "Profile", pageUrl: "/profile" }]} />
        <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
          Credit Details
        </h1>

        <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
          <div>
            <Menu />
          </div>
          <div>
            <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
              {dataLoading && (
                <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-16 tw-text-[#5d556c]">
                  <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
                  <p className="tw-m-0 tw-text-sm">Loading. Please wait.</p>
                </div>
              )}
              {!dataLoading && data.transactions.length === 0 && (
                <div className="tw-py-12 tw-text-center tw-text-sm tw-text-[#6b6577]">
                  No records found to display
                </div>
              )}
              {!dataLoading && data.transactions.length > 0 && (
                <>
                  <CreditPieChart creditData={data} />

                  <div className="tw-overflow-x-auto">
                    <table className="tw-w-full tw-border-collapse tw-text-sm">
                      <thead>
                        <tr className="tw-bg-[#f7f5fb] tw-text-left tw-text-[11px] tw-uppercase tw-tracking-wide tw-text-[#6b6577]">
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">N°</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Booking ID</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Tour Name</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Departure Date</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Booking Price</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Paid Amount</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Balance</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Earned Credit</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Operation</th>
                          <th className="tw-px-4 tw-py-3 tw-font-semibold">Credit Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {data.transactions.map((item: any, index: number) => {
                          const depDate = parsePlainDate(item.tour_start_date);
                          const formatter = new Intl.DateTimeFormat("tr-TR", {
                            day: "2-digit",
                            month: "2-digit",
                            year: "numeric",
                          });

                          const opPill =
                            item.type == "deposit"
                              ? "tw-bg-[#eafaf0] tw-text-[#1f8a4c]"
                              : "tw-bg-[#fdecec] tw-text-[#b23838]";
                          const statusPill =
                            item.status == "active"
                              ? "tw-bg-[#eafaf0] tw-text-[#1f8a4c]"
                              : "tw-bg-[#fef6e7] tw-text-[#b7791f]";

                          return (
                            <>
                              {item.ticket_id && (
                                <tr
                                  key={item.created_at}
                                  className="tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-text-[#3f3a4d] hover:tw-bg-[#faf9fc]"
                                >
                                  <td className="tw-px-4 tw-py-3">{index + 1}</td>
                                  <td className="tw-px-4 tw-py-3 tw-font-semibold tw-text-[#14101c]">{`BK${item.ticket_id}`}</td>
                                  <td className="tw-px-4 tw-py-3">{item.tour_name}</td>
                                  <td className="tw-px-4 tw-py-3">{formatter.format(depDate)}</td>
                                  <td className="tw-px-4 tw-py-3">
                                    {priceFormat({ amount: item.booking_amount, currency: data.currency })}
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    {priceFormat({ amount: item.paid_amount, currency: data.currency })}
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    {priceFormat({ amount: item.balance, currency: data.currency })}
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    {priceFormat({ amount: item.amount, currency: data.currency })}
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    <span className={`${pillBase} ${opPill}`}>{item.type}</span>
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    <span className={`${pillBase} ${statusPill}`}>{item.status}</span>
                                  </td>
                                </tr>
                              )}
                              {!item.ticket_id && (
                                <tr
                                  key={item.created_at}
                                  className="tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-text-[#3f3a4d] hover:tw-bg-[#faf9fc]"
                                >
                                  <td className="tw-px-4 tw-py-3">{index + 1}</td>
                                  <td className="tw-px-4 tw-py-3" colSpan={6}>
                                    {item.description}
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    {priceFormat({ amount: item.amount, currency: data.currency })}
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    <span className={`${pillBase} ${opPill}`}>{item.type}</span>
                                  </td>
                                  <td className="tw-px-4 tw-py-3">
                                    <span className={`${pillBase} ${statusPill}`}>{item.status}</span>
                                  </td>
                                </tr>
                              )}
                            </>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </>
              )}
            </div>

            {!dataLoading && data.transactions.length > 0 && (
              <div className="tw-mt-6">
                <h2 className="tw-mb-4 tw-text-center tw-text-lg tw-font-bold tw-text-[#14101c]">
                  Credit Summary
                </h2>
                <div className="tw-grid tw-grid-cols-2 tw-gap-4 lg:tw-grid-cols-4">
                  {summary.map((s) => (
                    <div
                      key={s.label}
                      className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-5 tw-text-center"
                    >
                      <p className="tw-m-0 tw-text-xs tw-font-medium tw-uppercase tw-tracking-wide tw-text-[#6b6577]">
                        {s.label}
                      </p>
                      <p className="tw-mt-1.5 tw-mb-0 tw-text-lg tw-font-bold tw-text-[#14101c]">
                        {priceFormat({ amount: s.value, currency: data.currency })}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
