import { apiClient } from "@/lib/apiClient";

/**
 * Login'li B2C kullanıcısının kredi/cüzdan özeti — apiv3 `GET /b2c/credits`
 * (account.php, Sanctum + app.token). Yanıt: { currency, available, pending,
 * transactions[] } (legacy /customer/credits ile aynı şekil). Sayfalama yok
 * (legacy de döndürmüyordu).
 */
export default async function getCreditDetailsList({ token }: { token: string }) {
    return apiClient("/b2c/credits", { auth: "sanctum", token });
}

export async function sendBrochureByMail({ email, name, slug }: { email: string; name: string, slug: string }) {
    // apiv3 B2C: POST /b2c/tours/{slug}/send-pdf (broşür e-postası).
    return apiClient(`/b2c/tours/${slug}/send-pdf`, {
        method: "POST",
        body: { email, first_name: name },
    });
}