import React, {useEffect, useState} from 'react'
import dynamic from "next/dynamic";

function precisionRoundMod(number:number, precision:number) {
    const factor = Math.pow(10, precision);
    const n = precision < 0 ? number : 0.01 / factor + number;
    return Math.round( n * factor) / factor;
}

const CreditPieChart = ({creditData} : {creditData: any}) => {
    const [totalEarnedCredit, setTotalEarnedCredit] = useState(0)
    const [totalSpentCredit, setTotalSpentCredit] = useState(0)

    useEffect(() => {
        for (const item of creditData.transactions) {
            if (item.type == "deposit"){
                setTotalEarnedCredit(prevState => prevState + item.amount)
            }
            else if (item.type == "withdraw"){
                setTotalSpentCredit(prevState => prevState + item.amount)
            }
        }
    }, [creditData]);

    // @ts-ignore
    const Chart = dynamic(() => import('react-apexcharts'), { ssr: true });

    const [bookingServiceTypeChart, setBookingServiceTypeChart]  =  useState({
        options: {},
        series: [],
    })

    useEffect(() => {
        if (totalEarnedCredit){
            setBookingServiceTypeChart({
                // @ts-ignore
                series: [precisionRoundMod(totalEarnedCredit, 2), precisionRoundMod(Math.abs(totalSpentCredit), 2)],
                options: {
                    labels: ["Total earned credit", "Spent amount"],
                    colors: ['#854ec9', '#FF5733', '#33FF57', '#3357FF', '#FFC300', '#900C3F'],
                },
            });
        }
    }, [totalSpentCredit, totalEarnedCredit]);

    if (bookingServiceTypeChart.series.length == 0) {
        return
    }

    return (
        <div className="tw-flex tw-flex-col tw-items-center tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-py-5">
            <Chart
                // @ts-ignore
                options={bookingServiceTypeChart.options} series={bookingServiceTypeChart.series}
                type="pie" width={400}/>
        </div>
    )
}

export default CreditPieChart